import json
from pathlib import Path
from typing import Any, Dict, Optional


class ConfigLoader:
    def __init__(self, config_path: str, defaults: Optional[Dict[str, Any]] = None):
        """Initialize the config loader with a path and optional defaults."""
        self.config_path = Path(config_path)
        self.defaults = defaults or {}
        self.config = self.load()

    def load(self) -> Dict[str, Any]:
        """Load config from file, falling back to defaults if file doesn't exist."""
        if self.config_path.exists():
            try:
                with open(self.config_path, 'r') as f:
                    return json.load(f)
            except (json.JSONDecodeError, IOError):
                return self.defaults.copy()
        return self.defaults.copy()

    def get(self, key: str, default: Any = None) -> Any:
        """Get a config value by key with optional fallback."""
        return self.config.get(key, default)

    def reload(self) -> None:
        """Reload config from disk."""
        self.config = self.load()

    def __getitem__(self, key: str) -> Any:
        """Allow dict-style access to config values."""
        return self.config[key]


if __name__ == "__main__":
    defaults = {
        "debug": False,
        "host": "localhost",
        "port": 8000,
    }

    loader = ConfigLoader("config.json", defaults)
    print(f"Debug mode: {loader.get('debug')}")
    print(f"Host: {loader['host']}")
